From b5dc5c7d55163db6a8872307476a1cdbabd8781d Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:27:21 +0100
Subject: [PATCH] applets/devicenotifier: offer Eject for optical discs that
 aren't mounted

An optical disc only offered Eject while it was mounted, so a disc that
was inserted but never mounted could not be ejected from the applet. Add
an Eject action to the disc's action list while it isn't mounted.

BUG: 469706
---
 applets/devicenotifier/CMakeLists.txt         |  1 +
 .../devicenotifier/actions/ejectaction.cpp    | 61 +++++++++++++++++++
 applets/devicenotifier/actions/ejectaction.h  | 34 +++++++++++
 applets/devicenotifier/actionsinfo.cpp        |  9 +++
 4 files changed, 105 insertions(+)
 create mode 100644 applets/devicenotifier/actions/ejectaction.cpp
 create mode 100644 applets/devicenotifier/actions/ejectaction.h

diff --git a/applets/devicenotifier/CMakeLists.txt b/applets/devicenotifier/CMakeLists.txt
index 3a2dcae27d..f4c2660b0d 100644
--- a/applets/devicenotifier/CMakeLists.txt
+++ b/applets/devicenotifier/CMakeLists.txt
@@ -28,6 +28,7 @@ plasma_add_applet(org.kde.plasma.devicenotifier
         actions/unmountaction.cpp
         actions/openwithfilemanageraction.cpp
         actions/checkaction.cpp
+        actions/ejectaction.cpp
         RESOURCES
         main.xml
         GENERATE_APPLET_CLASS
diff --git a/applets/devicenotifier/actions/ejectaction.cpp b/applets/devicenotifier/actions/ejectaction.cpp
new file mode 100644
index 0000000000..256ddf3780
--- /dev/null
+++ b/applets/devicenotifier/actions/ejectaction.cpp
@@ -0,0 +1,61 @@
+/*
+ * SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+ *
+ * SPDX-License-Identifier: GPL-2.0-or-later
+ */
+
+#include "ejectaction.h"
+
+#include <Solid/OpticalDisc>
+#include <Solid/OpticalDrive>
+
+#include <KLocalizedString>
+
+EjectAction::EjectAction(const std::shared_ptr<StorageInfo> &storageInfo, const std::shared_ptr<StateInfo> &stateInfo, QObject *parent)
+    : ActionInterface(storageInfo, stateInfo, parent)
+    , m_isOpticalDisc(m_storageInfo->device().is<Solid::OpticalDisc>())
+{
+    connect(m_stateInfo.get(), &StateInfo::stateChanged, this, &EjectAction::updateIsValid);
+}
+
+EjectAction::~EjectAction() = default;
+
+QString EjectAction::name() const
+{
+    return QStringLiteral("Eject");
+}
+
+void EjectAction::triggered()
+{
+    Solid::Device device = m_storageInfo->device();
+    auto *drive = device.as<Solid::OpticalDrive>();
+    if (!drive) {
+        drive = device.parent().as<Solid::OpticalDrive>();
+    }
+    if (drive) {
+        drive->eject();
+    }
+}
+
+bool EjectAction::isValid() const
+{
+    // When the disc is mounted, the default action already ejects it
+    return m_isOpticalDisc && !m_stateInfo->isMounted();
+}
+
+void EjectAction::updateIsValid()
+{
+    Q_EMIT isValidChanged(name(), isValid());
+}
+
+QString EjectAction::icon() const
+{
+    return QStringLiteral("media-eject");
+}
+
+QString EjectAction::text() const
+{
+    return i18n("Eject");
+}
+
+#include "moc_ejectaction.cpp"
diff --git a/applets/devicenotifier/actions/ejectaction.h b/applets/devicenotifier/actions/ejectaction.h
new file mode 100644
index 0000000000..3c93e6916f
--- /dev/null
+++ b/applets/devicenotifier/actions/ejectaction.h
@@ -0,0 +1,34 @@
+/*
+ * SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+ *
+ * SPDX-License-Identifier: GPL-2.0-or-later
+ */
+
+#pragma once
+
+#include "actioninterface.h"
+
+#include <stateinfo.h>
+
+class EjectAction : public ActionInterface
+{
+    Q_OBJECT
+
+public:
+    explicit EjectAction(const std::shared_ptr<StorageInfo> &storageInfo, const std::shared_ptr<StateInfo> &stateInfo, QObject *parent = nullptr);
+    ~EjectAction() override;
+
+    void triggered() override;
+
+    bool isValid() const override;
+
+    QString name() const override;
+    QString icon() const override;
+    QString text() const override;
+
+private Q_SLOTS:
+    void updateIsValid();
+
+private:
+    bool m_isOpticalDisc;
+};
diff --git a/applets/devicenotifier/actionsinfo.cpp b/applets/devicenotifier/actionsinfo.cpp
index 92cf83679a..261f167864 100644
--- a/applets/devicenotifier/actionsinfo.cpp
+++ b/applets/devicenotifier/actionsinfo.cpp
@@ -20,6 +20,7 @@

 #include <actions/checkaction.h>
 #include <actions/defaultaction.h>
+#include <actions/ejectaction.h>
 #include <actions/mountaction.h>
 #include <actions/mountandopenaction.h>
 #include <actions/openwithfilemanageraction.h>
@@ -156,6 +157,14 @@ void ActionsInfo::addActions()
         m_notValidActions[action->name()] = std::make_pair(m_actions.size(), action);
     }

+    action = new EjectAction(m_storageInfo, m_stateInfo, this);
+    connect(action, &ActionInterface::isValidChanged, this, &ActionsInfo::onIsActionValidChanged);
+    if (action->isValid()) {
+        m_actions.append(action);
+    } else {
+        m_notValidActions[action->name()] = std::make_pair(m_actions.size(), action);
+    }
+
     action = new OpenWithFileManagerAction(m_storageInfo, m_stateInfo, this);
     connect(action, &ActionInterface::isValidChanged, this, &ActionsInfo::onIsActionValidChanged);
     if (action->isValid()) {
